let navigationItems=OrbitNavigation.defaults.map(item=>({...item,iconData:'',custom:false}));
let navigationCategories=[{id:'work',name:'工作',color:'#d95656'},{id:'study',name:'学习',color:'#4285f4'},{id:'life',name:'生活',color:'#e9b52d'}];
let navigationDraft=null,navDrag=null,navClickBlockedUntil=0;
function navigationIcon(item){if(item.iconData)return '<img src="'+escapeHtml(item.iconData)+'" alt="" draggable="false">';if(item.iconSrc)return '<img src="'+escapeHtml(item.iconSrc)+'" alt="" draggable="false">';if(item.iconKey)return icon(item.iconKey);return '<span class="nav-initial-icon" aria-hidden="true">'+escapeHtml(OrbitNavigation.initial(displayNavigationName(item)))+'</span>';}
function displayNavigationName(item){const original=OrbitNavigation.defaults.find(n=>n.id===item.id);return OrbitI18n.text(item.name,prefs.language);}
function navigationItem(id){return navigationItems.find(item=>item.id===id);}
function renderWorkspaceNavigation(){
 if(navDrag?.active)return;
 const row=item=>'<a class="nav-item '+(item.shortcut?'shortcut-link ':'')+(item.id==='chatgpt'?'chatgpt-nav ':'')+(item.custom?'custom-link ':'')+(state.page===item.id?'active':'')+'" data-nav-id="'+escapeHtml(item.id)+'" href="#'+escapeHtml(item.id)+'" '+(state.page===item.id?'aria-current="page"':'')+'>'+(/^#[a-f0-9]{6}$/i.test(item.color||'')?'<i class="nav-color-dot" style="background:'+item.color+'" aria-hidden="true"></i>':'')+navigationIcon(item)+'<span class="nav-label">'+escapeHtml(displayNavigationName(item))+'</span>'+(item.position==='pinned'?'<svg class="nav-pin-star" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 14.8 8.7 21.1 9.6 16.5 14.1 17.6 20.4 12 17.4 6.4 20.4 7.5 14.1 2.9 9.6 9.2 8.7Z"/></svg>':'')+'</a>';
 const pinned=navigationItems.filter(item=>item.position==='pinned'),regular=navigationItems.filter(item=>item.position!=='pinned');
 $('#main-nav').innerHTML=(pinned.length?'<div class="nav-caption nav-group-caption">'+(prefs.language==='en'?'Pinned':'置顶')+'</div><div class="nav-group" data-nav-group="pinned">'+pinned.map(row).join('')+'</div>':'')+(pinned.length&&regular.length?'<div class="nav-group-divider" role="separator"></div>':'')+'<div class="nav-group" data-nav-group="regular">'+regular.map(row).join('')+'</div>';
}
async function loadNavigation(){if(window.orbitDesktop){const result=await window.orbitDesktop.getNavigation();if(result.ok){navigationItems=result.items;navigationCategories=result.categories||navigationCategories;render();}else toast(result.error);}else{navigationCategories=readStorage('navigationCategories',navigationCategories);const saved=readStorage('navigation',null);if(Array.isArray(saved)){navigationItems=readStorage('navigationVersion',1)===2?saved:OrbitNavigation.restoreRequired(saved);try{localStorage.setItem('orbit:navigation',JSON.stringify(navigationItems));localStorage.setItem('orbit:navigationVersion','2');localStorage.setItem('orbit:navigationCategories',JSON.stringify(navigationCategories));}catch{}render();}}}
function acceptNavigation(result){if(!result?.ok){toast(result?.error||'导航保存失败。');return false;}navigationItems=result.items;navigationCategories=result.categories||navigationCategories;if(!window.orbitDesktop){try{localStorage.setItem('orbit:navigation',JSON.stringify(navigationItems));localStorage.setItem('orbit:navigationVersion','2');localStorage.setItem('orbit:navigationCategories',JSON.stringify(navigationCategories));}catch{}}render();return true;}
function updateNavigationPreview(){if(!navigationDraft)return;const name=$('#nav-name')?.value||'';const item={...navigationDraft,name};$('#navigation-icon-preview').innerHTML=navigationIcon(item);}
function navigationModal(id){const item=navigationItem(id);navigationDraft=item?{...item}:{name:'',url:'',iconData:'',custom:true};openModal(item?'编辑导航页':'新增导航页','<form data-form="navigation"><label for="nav-name">名称</label><input id="nav-name" name="name" value="'+escapeHtml(navigationDraft.name)+'" maxlength="40" required autocomplete="off">'+(navigationDraft.internal?'':'<label for="nav-url">网页地址</label><input id="nav-url" name="url" type="text" inputmode="url" autocapitalize="off" spellcheck="false" value="'+escapeHtml(navigationDraft.url||'')+'" placeholder="https://" required>')+'<label>图标</label><div class="navigation-icon-picker"><span id="navigation-icon-preview"></span><button type="button" class="secondary-btn" data-action="navigation-icon">从桌面选择</button><button type="button" class="text-link" data-action="navigation-icon-default">默认图标</button></div><div class="modal-actions"><button type="button" class="secondary-btn" data-action="close-modal">取消</button><button type="submit" class="primary-btn">保存</button></div></form>');updateNavigationPreview();$('#nav-name').focus();}
async function pickNavigationIcon(){if(!window.orbitDesktop)return;const result=await window.orbitDesktop.pickNavigationIcon();if(!result.ok){toast(result.error);return;}if(result.canceled||!navigationDraft)return;navigationDraft.iconData=result.iconData;updateNavigationPreview();}
async function saveNavigationForm(form,fields){if(!navigationDraft)return;const input={...(navigationDraft.id?{id:navigationDraft.id}:{}),name:String(fields.get('name')||'').trim(),url:String(fields.get('url')||'').trim(),iconData:navigationDraft.iconData||'',position:navigationDraft.position||'normal',color:navigationDraft.color||'',category:navigationDraft.category||''};if(!navigationDraft.internal){try{input.url=OrbitUrl.normalizeWebUrl(input.url);}catch{toast('请输入完整的 http:// 或 https:// 网页地址。');return;}}const result=window.orbitDesktop?await window.orbitDesktop.saveNavigation(input):{ok:true,items:navigationDraft.id?navigationItems.map(item=>item.id===input.id?{...item,...input}:item):[...navigationItems,{...input,id:'nav-'+crypto.randomUUID(),custom:true}]};if(result.ok){closeModal();navigationDraft=null;acceptNavigation(result);toast('导航已保存。');}else toast(result.error);}
async function deleteNavigation(id){const old=navigationItem(id);if(!old)return;const result=window.orbitDesktop?await window.orbitDesktop.deleteNavigation(id):{ok:true,items:navigationItems.filter(item=>item.id!==id)};if(!result.ok){toast(result.error);return;}if(state.page===id){state.page='overview';history.replaceState(null,'','#overview');}acceptNavigation(result);toast('导航已删除。');}
async function commitNavigationOrder(ids){const result=window.orbitDesktop?await window.orbitDesktop.reorderNavigation(ids):{ok:true,items:ids.map(id=>navigationItem(id))};acceptNavigation(result);}
function finishNavigationDrag(commit){const drag=navDrag;if(!drag)return;clearTimeout(drag.timer);clearInterval(drag.scrollTimer);navDrag=null;document.body.classList.remove('navigation-dragging');drag.row.classList.remove('is-dragging');if(drag.row.hasPointerCapture?.(drag.pointerId))drag.row.releasePointerCapture(drag.pointerId);if(drag.active){navClickBlockedUntil=performance.now()+500;const ids=[...document.querySelectorAll('#main-nav [data-nav-id]')].map(row=>row.dataset.navId);if(commit&&ids.join('|')!==navigationItems.map(item=>item.id).join('|'))commitNavigationOrder(ids);else renderWorkspaceNavigation();}}
document.addEventListener('pointerdown',event=>{const row=event.target.closest('#main-nav [data-nav-id]');if(!row||event.button!==0||$('#modal').open)return;finishNavigationDrag(false);const drag={row,pointerId:event.pointerId,startX:event.clientX,startY:event.clientY,y:event.clientY,active:false};navDrag=drag;drag.timer=setTimeout(()=>{if(navDrag!==drag)return;drag.active=true;drag.row.classList.add('is-dragging');document.body.classList.add('navigation-dragging');try{drag.row.setPointerCapture(event.pointerId);}catch{}drag.scrollTimer=setInterval(()=>{const scroller=$('.sidebar-navigation'),rect=scroller.getBoundingClientRect();if(drag.y<rect.top+34)scroller.scrollTop-=12;else if(drag.y>rect.bottom-34)scroller.scrollTop+=12;},40);},400);});
document.addEventListener('pointermove',event=>{const drag=navDrag;if(!drag||drag.pointerId!==event.pointerId)return;drag.y=event.clientY;if(!drag.active){if(Math.hypot(event.clientX-drag.startX,event.clientY-drag.startY)>7)finishNavigationDrag(false);return;}event.preventDefault();const group=drag.row.parentElement,position=navigationItem(drag.row.dataset.navId)?.position||'normal';const rows=[...group.querySelectorAll('[data-nav-id]')].filter(row=>row!==drag.row&&(navigationItem(row.dataset.navId)?.position||'normal')===position);const before=rows.find(row=>{const rect=row.getBoundingClientRect();return event.clientY<rect.top+rect.height/2;});if(before)group.insertBefore(drag.row,before);else{const boundary=[...group.querySelectorAll('[data-nav-id]')].find(row=>row!==drag.row&&(navigationItem(row.dataset.navId)?.position||'normal')!==position);if(boundary&&position==='normal')group.insertBefore(drag.row,boundary);else group.append(drag.row);}},{passive:false});
document.addEventListener('pointerup',event=>{if(navDrag?.pointerId===event.pointerId)finishNavigationDrag(true);});
document.addEventListener('pointercancel',()=>finishNavigationDrag(false));
window.addEventListener('blur',()=>finishNavigationDrag(false));
document.addEventListener('click',event=>{if(event.target.closest('[data-nav-id]')&&performance.now()<navClickBlockedUntil){event.preventDefault();event.stopImmediatePropagation();}},true);
document.addEventListener('dragstart',event=>{if(event.target.closest('[data-nav-id]'))event.preventDefault();});
document.addEventListener('contextmenu',event=>{const row=event.target.closest('[data-nav-id]');if(!row)return;event.preventDefault();finishNavigationDrag(false);if(window.orbitDesktop)window.orbitDesktop.showNavigationMenu(row.dataset.navId);else navigationModal(row.dataset.navId);});
document.addEventListener('keydown',event=>{const row=event.target.closest('[data-nav-id]');if(!row||!event.altKey||!['ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();const ids=navigationItems.map(item=>item.id),index=ids.indexOf(row.dataset.navId),target=index+(event.key==='ArrowUp'?-1:1);if(target<0||target>=ids.length||(navigationItem(ids[index])?.position||'normal')!==(navigationItem(ids[target])?.position||'normal'))return;[ids[index],ids[target]]=[ids[target],ids[index]];commitNavigationOrder(ids).then(()=>$('#main-nav [data-nav-id="'+row.dataset.navId+'"]').focus());});
document.addEventListener('input',event=>{if(event.target.id==='nav-name')updateNavigationPreview();});
window.orbitDesktop?.onNavigationAction(action=>{if(action.action==='saved'){acceptNavigation(action.result);toast(prefs.language==='en'?'Navigation updated.':'导航已更新。');}else if(action.action==='new-category')navigationCategoryModal(action.id);else if(action.action==='edit')navigationModal(action.id);else if(action.action==='delete')deleteNavigation(action.id);});

function navigationCategoryModal(id){const en=prefs.language==='en',t=(zh,english)=>en?english:zh;const colors=[['#d95656','红色','Red'],['#4285f4','蓝色','Blue'],['#e9b52d','黄色','Yellow'],['#34a853','绿色','Green'],['#9b72cf','紫色','Purple'],['#dc78a4','粉色','Pink'],['#7e8999','灰色','Gray']];openModal(t('新增分类','Add category'),'<form data-form="navigation-category" data-navigation-id="'+escapeHtml(id)+'"><label for="category-name">'+t('分类名称','Category name')+'</label><input id="category-name" name="name" maxlength="24" required autocomplete="off"><label for="category-color">'+t('颜色','Color')+'</label><select id="category-color" name="color">'+colors.map(([color,zh,english])=>'<option value="'+color+'">'+t(zh,english)+'</option>').join('')+'</select><div class="modal-actions"><button type="button" class="secondary-btn" data-action="close-modal">'+t('取消','Cancel')+'</button><button type="submit" class="primary-btn">'+t('保存','Save')+'</button></div></form>');$('#category-name').focus();}
async function saveNavigationCategory(form){const fields=new FormData(form),input={name:String(fields.get('name')||'').trim(),color:String(fields.get('color')||'')};let result;if(window.orbitDesktop)result=await orbitDesktop.addNavigationCategory(input);else{if(navigationCategories.some(c=>c.name.toLocaleLowerCase()===input.name.toLocaleLowerCase())){toast(prefs.language==='en'?'This category name already exists.':'此分类名称已存在。');return;}const category={...input,id:'category-'+crypto.randomUUID()};result={ok:true,items:navigationItems,categories:[...navigationCategories,category],category};}if(!result.ok){toast(result.error);return;}acceptNavigation(result);const category=result.category,item=navigationItem(form.dataset.navigationId);if(item){const updated=window.orbitDesktop?await orbitDesktop.saveNavigation({id:item.id,category:category.id}):{ok:true,categories:navigationCategories,items:navigationItems.map(n=>n.id===item.id?{...n,category:category.id,color:category.color}:n)};if(!acceptNavigation(updated))return;}closeModal();toast(prefs.language==='en'?'Category saved.':'分类已保存。');}
document.addEventListener('submit',event=>{if(event.target.matches('form[data-form="navigation-category"]')){event.preventDefault();saveNavigationCategory(event.target);}});
